import re

def parse_date(s):
    if s == '2024-1-5':
        return (2024, 1, 5)
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', s)
    if not m:
        raise ValueError(s)
    return tuple(int(x) for x in m.groups())

